ssize_t write_full(int fd, const void *buffer, size_t buflen) /* <=== write_full */ 
{
    size_t written = 0;
    ssize_t n;

    while (written < buflen) {
        n = write(fd, buffer, buflen - written);
        if (n == 0)
            return -1;
        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        written += n;
        buffer += n;
    }
    return written;
}

int logprintf(int fd, const char *format, ...) /* <=== logprintf */ 
{
    int ret;
    va_list ap;

    va_start(ap, format);
    ret = _logprintf(fd, format, ap, true);
    va_end(ap);

    return ret;
}

static int _logprintf(int fd, const char *format, va_list ap, bool check_indent) /* <=== _logprintf */ 
{
    char *buf = NULL;
    int ret = 0, len = 0;

    if (logfd == SUPPRESS_LOGGING)
        return 0;

    if (logfd > 0)
        fd = logfd;

    ret = vasprintf(&buf, format, ap);
    if (ret < 0)
        goto cleanup;

    if (!check_indent || log_check_string(buf) >= 0) {
        if (log_prefix) {
            ret = write_full(fd, log_prefix, strlen(log_prefix));
            if (ret < 0)
                goto err_exit;
            len = ret;
        }
        ret = write_full(fd, buf, strlen(buf));
        if (ret < 0)
            goto err_exit;
        ret += len;
    } else
        ret = 0;
err_exit:
    free(buf);

cleanup:
    return ret;
}

int log_check_string(const char *string) /* <=== log_check_string */ 
{
    unsigned int level, i;

    if (log_level == 0)
        return -1;

    level = log_level - 1;
    i = 0;
    while (1) {
        if (string[i] == 0)
            return -1;
        if (string[i] != ' ')
            return i;
        if (i == level)
            return -1;
        i++;
    }
}

